test "t0" {
    assert (
        strip_comments(
            "apples, pears # and bananas\ngrapes\nbananas!apples", ["#", "!"]
        )
        == "apples, pears\ngrapes\nbananas"
    );;
}

test "t1" {
    assert (strip_comments("a #b\nc\nd $e f g", ["#", "$"]) == "a\nc\nd");;
}

